// Browser-only discoveries. Existing care, currency and furniture remain the source of truth.
(() => {
  const key='cozy-cat-adventures-v1', today=()=>new Date().toLocaleDateString('sv-SE');
  const gifts=[['sock','🧦','짝 잃은 양말','흔함'],['leaf','🍂','바삭한 나뭇잎','흔함'],['ribbon','🎀','분홍 리본','흔함'],['mouse','🐭','작은 쥐 인형','특별'],['bell','🔔','반짝 방울','특별'],['star','🌟','별빛 장난감','희귀'],['crown','👑','집사 왕관','희귀'],['letter','💌','애정 가득 편지','특별']];
  const memoryTypes={welcome:['🌷','우리의 첫 페이지'],nap:['🌙','함께한 첫 낮잠'],gift:['🎁','첫 보은 선물'],parcel:['📦','택배 탐험가'],play:['🎣','놀이의 달인'],taste:['🐟','취향을 알아낸 날'],knead:['🐾','처음 보여준 꾹꾹이'],belly:['💛','마음을 연 순간'],lap:['💤','무릎 위 단잠'],gold:['👑','황금빛 첫 등반'],rain:['🌧','빗소리를 듣던 날'],night:['🌙','한밤의 우다다'],sun:['☀️','햇살 아래 휴식']};
  let data={care:0,received:0,collection:{},parcelDay:'',discovered:{},memories:[],playWins:0};
  try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object'){for(const n of ['care','received','playWins'])if(Number.isFinite(saved[n]))data[n]=Math.max(0,Math.floor(saved[n]));if(typeof saved.parcelDay==='string')data.parcelDay=saved.parcelDay;for(const [id]of gifts)if(Number.isFinite(saved.collection?.[id]))data.collection[id]=Math.max(0,Math.floor(saved.collection[id]));if(saved.discovered&&typeof saved.discovered==='object')for(const breed of Object.keys(characters))data.discovered[breed]=['snack','toy','rest'].filter(k=>saved.discovered[breed]?.includes(k));if(Array.isArray(saved.memories))data.memories=saved.memories.filter(m=>memoryTypes[m.id]&&characters[m.breed]&&typeof m.name==='string'&&typeof m.date==='string').slice(0,60)}}catch{}
  const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node};
  const button=(text,fn)=>{const node=el('button',text,'adventure-button');node.type='button';node.onclick=fn;return node};
  const trigger=button('🎁 추억과 모험',()=>{draw();dialog.showModal()});trigger.classList.add('adventure-menu');document.querySelector('.room-tools').append(trigger);
  const dialog=el('dialog');dialog.id='adventureDialog';dialog.setAttribute('aria-labelledby','adventureTitle');
  const heading=el('div',undefined,'dialog-heading'),title=el('h2','추억과 모험');title.id='adventureTitle';const close=button('✕',()=>dialog.close());close.setAttribute('aria-label','추억과 모험 닫기');heading.append(title,close);
  const intro=el('p','조금씩 알아가고, 오래 기억해요. 쉬었다 와도 언제나 반가워요.','adventure-intro');
  const nav=el('nav',undefined,'adventure-tabs');nav.setAttribute('aria-label','모험 콘텐츠');const content=el('div');content.id='adventureContent';const message=el('p','새로운 발견이 기다리고 있어요.','adventure-message');message.setAttribute('role','status');
  dialog.append(heading,intro,nav,content,message);document.querySelector('main').append(dialog);
  let page='gifts',round=null;const morePlay=button('🎯 레이저·생선·숨바꼭질',()=>{ $('playDialog').close();page='play';draw();dialog.showModal() });$('playDialog').append(morePlay);const pages=[['gifts','🎁 보은·도감'],['parcel','📦 택배'],['taste','🐾 취향'],['play','🎯 미니게임'],['album','📸 앨범'],['bond','💛 특별 행동']];
  for(const [id,label]of pages){const b=button(label,()=>{stopRound();page=id;draw()});b.dataset.page=id;nav.append(b)}
  function save(){try{localStorage.setItem(key,JSON.stringify(data))}catch{message.textContent='이 브라우저에서는 추억을 저장할 수 없어요.'}}
  function remember(id){if(data.memories.some(m=>m.id===id))return;data.memories.push({id,breed:$('cat').dataset.character,name:catName,date:today()});save()}
  function notify(text){message.textContent=text;say(text)}
  function reward(xp,heartsCount=0,play=false){state.hearts+=heartsCount;state.happy=Math.min(100,state.happy+5);window.dispatchEvent(new CustomEvent('cat-adventure-reward',{detail:{xp,play}}));save()}
  function available(){if(state.busy||state.sleeping||!$('playField').hidden||round){notify('하던 일을 마치고, 잠에서 깬 뒤 함께해요.');return false}return true}
  function receiveGift(){const n=data.received++;const index=n%5===4?5+(Math.floor(n/5)%2):[0,1,2,3,4,7][n%6];const item=gifts[index];data.collection[item[0]]=(data.collection[item[0]]||0)+1;remember('gift');notify(item[1]+' '+item[2]+'! 집사에게 주는 선물이에요.');save()}
  const oldAct=act;act=async action=>{if(round)return{ok:false,message:'미니게임을 마친 뒤 돌봐 주세요.'};const result=await oldAct(action);if(result.ok){if(action==='nap'&&state.sleeping)remember('nap');else if(action!=='nap'){data.care++;if(data.care%5===0)receiveGift()}save();if(dialog.open)draw()}return result};
  function card(icon,name,description){const c=el('article',undefined,'adventure-card');c.append(el('span',icon,'adventure-icon'),el('h3',name),el('p',description));return c}
  function draw(){nav.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.page===page)));content.replaceChildren();if(page==='gifts')drawGifts();if(page==='parcel')drawParcel();if(page==='taste')drawTaste();if(page==='play')drawPlay();if(page==='album')drawAlbum();if(page==='bond')drawBond()}
  function grid(){const g=el('div',undefined,'adventure-grid');content.append(g);return g}
  function drawGifts(){content.append(el('h3','집사에게 주는 작은 보은'),el('p','밥·간식·쓰다듬기 5번마다 선물 하나! 다음 선물까지 '+(5-data.care%5)+'번 · 수집 '+gifts.filter(i=>data.collection[i[0]]).length+'/'+gifts.length));const g=grid();for(const [id,icon,name,rarity]of gifts)g.append(card(data.collection[id]?icon:'❔',data.collection[id]?name:'아직 못 찾은 선물',rarity+(data.collection[id]?' · '+data.collection[id]+'개':' · 함께 돌보며 발견해요')));content.append(el('p','다섯 번째 보은 선물마다 희귀 선물을 가져와요.','adventure-hint'))}
  function drawParcel(){const done=data.parcelDay===today();const themes=['꽃무늬 상자','별 스티커 상자','커다란 리본 상자'];const index=hash(today())%themes.length;content.append(card(done?'📭':'📦',themes[index],done?'오늘의 탐험은 끝! 내일 새 상자가 와요.':'하루 한 번, 원하는 방법으로 상자를 탐험해요.'));for(const method of ['쏙 들어가기','앞발로 톡톡']){const b=button(method,()=>{if(data.parcelDay===today()||!available())return;data.parcelDay=today();const item=gifts[(hash(today())+(method==='쏙 들어가기'?0:1))%gifts.length];data.collection[item[0]]=(data.collection[item[0]]||0)+1;remember('parcel');reward(5,10);notify(item[1]+' '+item[2]+' 발견! 하트 +10, 친밀도 +5');draw()});b.disabled=done;content.append(b)}}
  function hash(text){return Array.from(text).reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7)}
  const choices={snack:['참치 간식','연어 간식','닭고기 간식'],toy:['깃털 장난감','실타래','쥐 인형'],rest:['햇살 창가','폭신한 쿠션','조용한 상자']};const labels={snack:'좋아하는 간식',toy:'좋아하는 장난감',rest:'좋아하는 잠자리'};
  function drawTaste(){const breed=$('cat').dataset.character,seed=hash(breed),found=data.discovered[breed]||[];content.append(el('h3',catName+'의 취향 노트'),el('p',['호기심 많은 탐험가','느긋한 햇살 애호가','애교 많은 장난꾸러기'][seed%3]+' · 좋아하는 것을 찾으면 특별 반응과 하트 +5!'));const g=grid();Object.entries(choices).forEach(([kind,options],i)=>{const favorite=(seed+i*7)%3,c=card(['🐟','🧶','🛏️'][i],labels[kind],found.includes(kind)?'발견 완료: '+options[favorite]:'하나씩 시도하며 알아가요.');options.forEach((option,index)=>c.append(button(option,()=>{if(!available())return;if(index===favorite){const known=data.discovered[breed]||=[];if(!known.includes(kind)){known.push(kind);reward(4,5);remember('taste');notify('고르릉! '+option+' 정말 좋아해. 취향 발견 · 하트 +5')}else notify(option+'! 내 취향을 기억해 줬구나.');hearts()}else notify('킁킁… 오늘은 다른 게 더 끌린다냥.');draw()})));g.append(c)})}
  function stopRound(){if(!round)return;clearInterval(round.timer);round=null;state.busy=false;render()}
  dialog.addEventListener('close',stopRound);
  function drawPlay(){content.append(el('p','시간 제한과 실패 벌점 없이 즐겨요. 완료하면 하트 +8, 친밀도 +10!'));for(const [mode,label,desc]of [['laser','🔴 레이저 따라잡기','움직이는 빛을 다섯 번 잡아요.'],['fish','🐟 생선 잡기','헤엄치는 생선을 다섯 번 잡아요.'],['hide','📦 상자 숨바꼭질','고양이가 숨은 상자를 찾아요. 세 번 찾으면 성공!']]){const c=card('',label,desc);c.append(button('시작하기',()=>startRound(mode)));content.append(c)}}
  function startRound(mode){if(!available())return;round={mode,hits:0,target:Math.floor(Math.random()*3),timer:null};state.busy=true;render();content.replaceChildren();const score=el('p','찾은 횟수 0 / '+(mode==='hide'?3:5));score.setAttribute('role','status');const field=el('div',undefined,'adventure-field');const stop=button('그만 놀기',()=>{stopRound();draw()});content.append(score,field,stop);const move=b=>{b.style.left=(8+Math.random()*68)+'%';b.style.top=(12+Math.random()*56)+'%'};
    function hit(){if(!round)return;round.hits++;const target=mode==='hide'?3:5;score.textContent='찾은 횟수 '+round.hits+' / '+target;notes();if(round.hits>=target){stopRound();data.playWins++;remember('play');reward(10,8,true);notify('다 찾았다냥! 하트 +8, 친밀도 +10');draw();return}if(mode==='hide'){round.target=Math.floor(Math.random()*3);score.textContent+=' · 다시 숨었어요!'}}
    if(mode==='hide'){field.classList.add('hide-field');for(let i=0;i<3;i++)field.append(button('📦 '+(i+1)+'번 상자',()=>{if(!round)return;if(round.target===i)hit();else score.textContent='여기는 비었어요! 다른 상자를 찾아봐요.'}))}else{const target=button(mode==='laser'?'🔴':'🐟',()=>{if(round){hit();if(round)move(target)}});target.className='catch-target';target.setAttribute('aria-label',mode==='laser'?'레이저 잡기':'생선 잡기');field.append(target);move(target);round.timer=setInterval(()=>{if(document.activeElement!==target)move(target)},mode==='laser'?1400:1900);target.focus()}}
  function portrait(memory){const svg=document.querySelector('.cat-sprite').cloneNode(true);svg.removeAttribute('aria-label');svg.setAttribute('aria-hidden','true');svg.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));const cat=svg.querySelector('.cat-design');cat.dataset.character=memory.breed;['fur','face','bib','tail','stripe','eyes','mouth'].forEach((p,i)=>cat.style.setProperty('--'+p,characters[memory.breed].colors[i]));return svg}
  function drawAlbum(){content.append(el('p','특별한 순간이 자동으로 사진 카드에 남아요. '+data.memories.length+' / '+Object.keys(memoryTypes).length+'장의 추억'));const g=grid();for(const m of [...data.memories].reverse()){const c=card(memoryTypes[m.id][0],memoryTypes[m.id][1],m.name+' · '+m.date);const photo=el('div',undefined,'memory-photo');photo.dataset.memory=m.id;photo.append(portrait(m));c.prepend(photo);g.append(c)}}
  const specials=[['knead','🐾','꾹꾹이',40,'집사 옆에서 앞발을 꾹꾹…'],['belly','💛','배 보여주기',100,'너라면 안심이야. 발라당!'],['lap','💤','무릎 잠자기',180,'가장 포근한 곳은 집사 무릎이야.']];
  function animate(kind,text,memory){if(!available())return;state.busy=true;game.classList.add('special-'+kind);notify(text);remember(memory||kind);render();setTimeout(()=>{game.classList.remove('special-'+kind);state.busy=false;render()},4000)}
  function drawBond(){const xp=Number(game.dataset.bondXp)||0;content.append(el('p','함께 쌓은 친밀도 '+xp+' · 돌봄과 놀이로 특별한 행동을 만나요.'));const g=grid();for(const [id,icon,name,need,text]of specials){const c=card(icon,name,xp>=need?'마음을 열었어요!':'친밀도 '+need+'에 열려요 · '+(need-xp)+' 더 필요');const b=button(xp>=need?'함께하기':'아직 기다리는 중',()=>{animate(id,text);if(state.busy)dialog.close()});b.disabled=xp<need;c.append(b);g.append(c)}if(document.querySelector('[data-item="goldTower"]')){const b=button('👑 순금 캣타워 올라가기',()=>{animate('gold','반짝반짝, 여기서 세상이 다 보여!','gold');if(state.busy)dialog.close()});content.append(b)}}
  const weatherButton=button('',()=>{const w=weather();animate(w.id,w.text,w.memory)});weatherButton.className='weather-story';document.querySelector('.day-label').prepend(weatherButton);
  function weather(){const hour=new Date().getHours();if(hour>=20||hour<6)return{id:'night',label:'🌙 고요한 밤 · 우다다',text:'집사야, 밤 운동 시작이다냥!',memory:'night'};return hash(today())%3===0?{id:'rain',label:'🌧 빗소리 오후 · 창가 구경',text:'토독토독… 빗방울 구경하자.',memory:'rain'}:{id:'sun',label:'☀️ 햇살 좋은 날 · 볕 쬐기',text:'따뜻한 햇살이 배에 닿는다냥.',memory:'sun'}}
  // Weather is a cozy in-game daily scene, not a location-based forecast.
  const dayLabel=document.querySelector('.day-label');for(const node of [...dayLabel.childNodes])if(node.nodeType===Node.TEXT_NODE)node.textContent='';weatherButton.title='게임 속 날씨와 시간에 따라 달라지는 특별 행동';
  function refreshWeather(){const w=weather();weatherButton.textContent=w.label;game.dataset.weather=w.id}refreshWeather();setInterval(refreshWeather,60000);
  remember('welcome');window.addEventListener('pagehide',()=>{stopRound();save()});
})();
